export class LocalStorage {
  /**
   * Retrieve all entries from window.localStorage.
   * @returns An object mapping keys to their string values (or null if a key has no value).
   */
  public static getAllLocalStorageItems(): Record<string, string | null> {
    const items: Record<string, string | null> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key !== null) {
        items[key] = localStorage.getItem(key);
      }
    }
    return items;
  }

  /**
   * Write all entries from an object into window.localStorage.
   * @param dataObject  An object whose string values will be stored under their corresponding keys.
   */
  public static setAllLocalStorageItems(dataObject: Record<string, string>): void {
    for (const [key, value] of Object.entries(dataObject)) {
      localStorage.setItem(key, value);
    }
  }
}
