import React, { createContext, useEffect, useState } from 'react';
import { isSafariOniOS, isSafariOniPad, sanitizeUrl } from '../utils';
import { repSocialEmbedded, repSocialExtension } from '../instances';
import { ExtensionEventMap } from '../extension';
import { EmbededEventMap } from '../embeded';

export interface RepSocialState {
  communityUrl: string;
  communityUrlId: string;
  isEmbedded: boolean;
  isEmbeddedInIframe: boolean;
  isMobileEmbedded: boolean;
  isMobileIOSEmbedded: boolean;
  isExtension: boolean;
  isRepSocialIntegrated: boolean;
  /**
   * @extension This state is used to track if the current site has RepSocial embedded.
   */
  currentSiteHasRepSocialEmbedded?: boolean;
}

export const RepSocialContext = createContext<RepSocialState | undefined>(undefined);

export const RepSocialProvider: React.FC<React.PropsWithChildren<object>> = ({ children }) => {
  const [communityUrl, setCommunityUrl] = useState('');
  const communityUrlId = sanitizeUrl(communityUrl);
  const isEmbedded = repSocialEmbedded.isEmbedded;
  const isEmbeddedInIframe = repSocialEmbedded.isEmbeddedInIframe;
  const isMobileIOSEmbedded = repSocialEmbedded.isMobileIOSEmbedded;
  const isMobileEmbedded = repSocialEmbedded.isMobileEmbedded;
  const isExtension = repSocialExtension.isChromeExtension;
  const isRepSocialIntegrated = isEmbedded || isExtension;

  const [currentSiteHasRepSocialEmbedded, setCurrentSiteHasRepSocialEmbedded] = useState(false);

  // Extension setup
  useEffect(() => {
    if (!repSocialExtension.isChromeExtension) return;

    const onTabActivated: ExtensionEventMap['onTabActivated'] = (tab) => {
      if (tab.url) setCommunityUrl(tab.url);
    };
    const onActiveTabEmbeded: ExtensionEventMap['onActiveTabEmbeded'] = ({
      isRepEmbedded,
      closeExtension,
    }) => {
      setCurrentSiteHasRepSocialEmbedded(isRepEmbedded);
      if (closeExtension) {
        window.close();
      }
    };
    const onStartLoadingRepIframe: ExtensionEventMap['onStartLoadingRepIframe'] = () => {
      setCurrentSiteHasRepSocialEmbedded(true);
    };

    const setup = async () => {
      repSocialExtension.on('onTabActivated', onTabActivated);
      repSocialExtension.on('onActiveTabEmbeded', onActiveTabEmbeded);
      repSocialExtension.on('onStartLoadingRepIframe', onStartLoadingRepIframe);

      const activeTab = await repSocialExtension.getActiveTab();
      const activeTabId = activeTab?.id;
      if (activeTab?.url) setCommunityUrl(activeTab.url);
      if (activeTabId) {
        const isRepEmbedded = await repSocialExtension.isRepSocialEmbeddedInTab(activeTabId);
        repSocialExtension.emit('onActiveTabEmbeded', { isRepEmbedded });
      }
    };

    setup();
    console.log('RepSocial extension has setup');

    return () => {
      repSocialExtension.off('onTabActivated', onTabActivated);
      repSocialExtension.off('onActiveTabEmbeded', onActiveTabEmbeded);
      repSocialExtension.off('onStartLoadingRepIframe', onStartLoadingRepIframe);
    };
  }, []);

  // Embeded setup
  useEffect(() => {
    const onParentUrlChange: EmbededEventMap['onParentUrlChange'] = (url) => {
      setCommunityUrl(url);
    };

    const setup = async () => {
  /* ------------------------------------------------------------------
   *  Extract `currentTabUrl` from the current page’s query string.
   *    - Purpose: forward the parent tab’s URL to the iframe so
   *      RepSocial knows which site opened the embed.
   *    - Also mark iOS embeds to handle Safari-specific quirks.
   *    Example:
   *      https://embed.rep.run?currentTabUrl=https%3A%2F%2Fexample.com
   *      ➜ currentTabUrl === "https://example.com"
   * ------------------------------------------------------------------ */
      const { search } = window.location;
      const currentTabUrl = new URLSearchParams(search).get('currentTabUrl');
      if (currentTabUrl && typeof currentTabUrl === 'string') {
        if (isSafariOniOS() || isSafariOniPad()) {
          repSocialEmbedded.isMobileIOSEmbedded = true
        }
        repSocialEmbedded.parentTabUrl = currentTabUrl;
      }
      if (repSocialEmbedded.parentTabUrl) {
        setCommunityUrl(repSocialEmbedded.parentTabUrl);
      }
      repSocialEmbedded.on('onParentUrlChange', onParentUrlChange);

      const originalOpen = window.open;

      window.open = function (url, name, specs) {
        if (name === '_blank' && repSocialEmbedded.isEmbedded) {
          const _url = url?.toString();
          if (_url) {
            repSocialEmbedded.openNewTab({ url: _url });
            return null;
          }
        }

        // Call the original function with the same arguments
        return originalOpen(url, name, specs);
      };
    };

    setup();
    console.log('RepSocial embedded has setup');

    return () => {
      repSocialEmbedded.off('onParentUrlChange', onParentUrlChange);
    };
  }, []);

  return (
    <RepSocialContext.Provider
      value={{
        communityUrl,
        communityUrlId,
        isEmbedded,
        isEmbeddedInIframe,
        isMobileEmbedded,
        isMobileIOSEmbedded,
        isExtension,
        isRepSocialIntegrated,
        currentSiteHasRepSocialEmbedded,
      }}
    >
      {children}
    </RepSocialContext.Provider>
  );
};
