export const isSafariOniOS = () => {
  const ua = window.navigator.userAgent
  const isIOSApple = /iP(hone|od|ad)/i.test(ua)
  const isWebKit = /WebKit/i.test(ua)
  const isChromeOnIOS = /CriOS/i.test(ua)
  return isIOSApple && isWebKit && !isChromeOnIOS
}
export const isSafariOniPad = () => {
  const ua = navigator.userAgent
  const isIPad =
    /iPad/.test(ua) ||
    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)
  const isWebKit = /WebKit/.test(ua)
  const isNotChrome = !/CriOS|FxiOS|OPiOS|EdgiOS/.test(ua)

  return isIPad && isWebKit && isNotChrome
}