import { EmbededAction, EmbededStorageKey } from './constants';
import { StorageAccess } from './storage-access';

/** List of all supported events */
export type EmbededEvent = 'onParentUrlChange' | 'onSuccessGMSubscription';

/** Map each event to its listener signature */
export interface EmbededEventMap {
  onParentUrlChange: (url: string) => void;
  onSuccessGMSubscription: (data?: unknown) => void;
}

export class RepSocialEmbedded {
  /** A listeners array for each event key */
  private listeners: {
    [K in EmbededEvent]: Array<EmbededEventMap[K]>;
  } = {
    onParentUrlChange: [],
    onSuccessGMSubscription: [],
  };
  constructor() {
    StorageAccess.init();
    this.initMessageListener();
  }

  /** Subscribe to an event */
  public on<K extends EmbededEvent>(event: K, callback: EmbededEventMap[K]): void {
    this.listeners[event].push(callback);
  }

  /** Unsubscribe from an event */
  public off<K extends EmbededEvent>(event: K, callback: EmbededEventMap[K]): void {
    const arr = this.listeners[event];
    const idx = arr.indexOf(callback);
    if (idx !== -1) arr.splice(idx, 1);
  }

  public emit<K extends EmbededEvent>(event: K, ...args: Parameters<EmbededEventMap[K]>): void {
    this.listeners[event].forEach((listener) => {
      try {
        // cast listener ➔ a generic function so TS will allow the spread
        (listener as (...callbackArgs: unknown[]) => void)(...args);
      } catch (err) {
        console.error(`Error in ${event} listener`, err);
      }
    });
  }

  /** Listen for messages from the parent frame once */
  private initMessageListener(): void {
    if (typeof window === 'undefined') return;

    window.addEventListener('message', (e: MessageEvent) => {
      const { action, data } = e.data || {};

      switch (action) {
        case EmbededAction.SuccessGMSubscription: {
          this.emit('onSuccessGMSubscription', data);
          break;
        }

        case EmbededAction.UrlChange: {
          const parentUrl = data;
          if (typeof parentUrl === 'string' && parentUrl) {
            this.parentTabUrl = parentUrl;
          }
        }
      }
    });
  }

  /** Where the iframe is embedded */
  public get parentTabUrl(): string {
    return localStorage.getItem(EmbededStorageKey.parentTabUrl) ?? '';
  }
  public set parentTabUrl(url: string) {
    localStorage.setItem(EmbededStorageKey.parentTabUrl, url);
    this.emit('onParentUrlChange', url);
  }

  /** iOS embed flag */
  public get isMobileIOSEmbedded(): boolean {
    if (typeof localStorage === 'undefined') return false;
    return localStorage.getItem(EmbededStorageKey.isEmbeddedMobileIOS) === 'true';
  }
  public set isMobileIOSEmbedded(value: boolean) {
    if (typeof localStorage === 'undefined') return;
    localStorage.setItem(EmbededStorageKey.isEmbeddedMobileIOS, String(value));
  }

  public get isEmbeddedInIframe(): boolean {
    return typeof window !== 'undefined' && window.self !== window.top;
  }

  /** Inside an iframe or mobile embed? */
  public get isEmbedded(): boolean {
    return this.isEmbeddedInIframe || this.isMobileEmbedded;
  }

  /** Any mobile embed container? */
  public get isMobileEmbedded(): boolean {
    if (typeof window === 'undefined') return false;
    if (this.isMobileIOSEmbedded) return true;
    return Boolean(document.documentElement.getAttribute('data-rep-social'));
  }

  public openNewTab({ url }: { url: string }) {
    const message = {
      action: EmbededAction.OpenNewTab,
      data: url,
    };

    window.parent.postMessage(message, '*');
  }

  public redirect({ url }: { url: string }) {
    const message = {
      action: EmbededAction.Redirect,
      data: url,
    };

    window.parent.postMessage(message, '*');
  }

  public communicateToEmbedded(
    action: EmbededAction,
    data?: EmbededEventMap[EmbededEvent] | Record<string, unknown>,
  ): void {
    window.postMessage(
      {
        action,
        data,
      },
      '*',
    );
  }
}

export * from './constants';
