// Extension actions that emit from the Rep extension -> background:
export enum ExtensionAction {
  // Kyc callback
  KYCVerification = 'KYCVerification',

  SuccessGMSubscription = 'successGMSubscription',

  // redirect active tab
  redirect = 'redirect',
  openNewTab = 'openNewTab',
  // check tab embeded
  repEmbedded = 'repEmbedded',

  // This event is sent from: current site (which is embed rep iframe) -> content.js -> background.js -> Rep extension
  startLoadingRepIframe = 'startLoadingRepIframe', // V
  tabActivated = 'tabActivated', // V
  refreshUI = 'refreshUI',
}

export const ExtensionStorageKey = {
  ExtensionId: 'extensionId',
};
