import { ExtensionAction } from './constants';

interface ExtensionConfig {
  isDevMode?: boolean;
  onTabActivated?: (tab: chrome.tabs.Tab) => void;
  onStartLoadingRepIframe?: () => void;
  onActiveTabEmbeded?: (params: { isRepEmbedded: boolean }) => void;
  onKycCompleted?: (params: { isSuccess: boolean; message: string } | undefined) => void;
}

export type ExtensionEvent =
  | 'onTabActivated'
  | 'onStartLoadingRepIframe'
  | 'onActiveTabEmbeded'
  | 'onKycCompleted'
  | 'onSuccessGMSubscription';

/**
 * Map each event string to the exact callback signature.
 */
export interface ExtensionEventMap {
  onTabActivated: (tab: chrome.tabs.Tab) => void;
  onStartLoadingRepIframe: () => void;
  onActiveTabEmbeded: (params: { isRepEmbedded: boolean; closeExtension?: boolean }) => void;
  onKycCompleted: (params: { isSuccess: boolean; message: string } | undefined) => void;
  onSuccessGMSubscription: (data?: unknown) => void;
}

export class RepSocialExtension {
  private config: ExtensionConfig;
  /**
   * For each event key, keep an array of listeners.
   */
  private listeners: {
    [K in ExtensionEvent]: Array<ExtensionEventMap[K]>;
  } = {
    onTabActivated: [],
    onStartLoadingRepIframe: [],
    onActiveTabEmbeded: [],
    onKycCompleted: [],
    onSuccessGMSubscription: [],
  };

  constructor(config: ExtensionConfig = {}) {
    this.config = config;
    this.initListeners();
  }

  /**
   * Register a listener for a given event.
   */
  public on<K extends ExtensionEvent>(eventName: K, callback: ExtensionEventMap[K]): void {
    this.listeners[eventName].push(callback);
  }

  /**
   * Remove a listener for a given event.
   */
  public off<K extends ExtensionEvent>(eventName: K, callback: ExtensionEventMap[K]): void {
    const arr = this.listeners[eventName];
    const idx = arr.indexOf(callback);
    if (idx !== -1) {
      arr.splice(idx, 1);
    }
  }

  public destroyed() {
    if (
      this.isChromeExtension &&
      typeof window !== 'undefined' &&
      window?.chrome?.runtime?.onMessage &&
      window?.chrome?.runtime?.onMessageExternal
    ) {
      window.chrome.runtime.onMessage.removeListener(this.onMessage);
      window.chrome.runtime.onMessageExternal.removeListener(this.onMessageToken);
    }
  }

  private initListeners() {
    if (
      this.isChromeExtension &&
      typeof window !== 'undefined' &&
      window?.chrome?.runtime?.onMessage &&
      window?.chrome?.runtime?.onMessageExternal
    ) {
      window.chrome.runtime.onMessage.addListener(this.onMessage);
      window.chrome.runtime.onMessageExternal.addListener(this.onMessageToken);
      if (typeof this.config.onTabActivated === 'function') {
        this.listeners.onTabActivated.push(this.config.onTabActivated);
      }
      if (typeof this.config.onActiveTabEmbeded === 'function') {
        this.listeners.onActiveTabEmbeded.push(this.config.onActiveTabEmbeded);
      }
      if (typeof this.config.onKycCompleted === 'function') {
        this.listeners.onKycCompleted.push(this.config.onKycCompleted);
      }
      if (typeof this.config.onStartLoadingRepIframe === 'function') {
        this.listeners.onStartLoadingRepIframe.push(this.config.onStartLoadingRepIframe);
      }
    }
  }

  private onMessage: Parameters<typeof window.chrome.runtime.onMessage.addListener>[0] = async (
    request,
    sender,
    sendResponse,
  ) => {
    switch (request.action) {
      case ExtensionAction.KYCVerification: {
        this.emit('onKycCompleted', request?.data);
        break;
      }

      case ExtensionAction.SuccessGMSubscription: {
        this.emit('onSuccessGMSubscription', request?.data);
        break;
      }

      case ExtensionAction.repEmbedded: {
        this.emit('onActiveTabEmbeded', {
          isRepEmbedded: true,
          closeExtension: !!request?.data?.closeExtension,
        });
        break;
      }

      // TODO: Rename to refreshSidePanelUI
      case ExtensionAction.refreshUI: {
        const id = window.chrome.runtime.id;
        window.location.href = `chrome-extension://${id}/index.html`;
        break;
      }

      case ExtensionAction.startLoadingRepIframe:
      case ExtensionAction.tabActivated: {
        // auto close sidepanel when there's repsocial embedded in active tab
        const activeTab = await this.getActiveTab();
        const activeTabId = activeTab?.id;
        if (activeTabId) {
          const isRepEmbedded = await this.isRepSocialEmbeddedInTab(activeTabId);
          this.emit('onActiveTabEmbeded', { isRepEmbedded, closeExtension: isRepEmbedded });
        }

        if (request.action === ExtensionAction.startLoadingRepIframe) {
          this.emit('onStartLoadingRepIframe');
        }
        if (request.action === ExtensionAction.tabActivated) {
          this.emit('onTabActivated', request.tab);
        }
        break;
      }

      default: {
        console.warn(`Unknown action: ${request.action}`);
        break;
      }
    }

    if (request.action === ExtensionAction.refreshUI) {
      sendResponse({
        status: window.location.origin + window.location.pathname,
      });
      const id = window.chrome.runtime.id;
      window.location.href = `chrome-extension://${id}/index.html`;
    }
  };

  private onMessageToken: Parameters<
    typeof window.chrome.runtime.onMessageExternal.addListener
  >[0] = (message) => {
    if (message.token) {
      const data = message.token;
      for (const key in data) {
        if (Object.prototype.hasOwnProperty.call(data, key)) {
          const item: Record<string, unknown> = {};
          item[key] = data[key];
          localStorage.setItem(key, data[key] as string);
          window.chrome.storage.local.set(item, () => {
            if (window.chrome.runtime.lastError) {
              console.error(`Error setting ${key}:`, window.chrome.runtime.lastError);
            } else {
              console.log(`${key} saved successfully.`);
            }
          });
        }
      }
      const id = window.chrome.runtime.id;
      window.location.href = `chrome-extension://${id}/index.html`;
      // Optionally, you could emit an event like 'onKycCompleted' if that flow is relevant here.
    }
  };

  public isRepSocialEmbeddedInTab = async (tabId: number): Promise<boolean> => {
    return new Promise((resolve) => {
      window.chrome.tabs?.sendMessage(
        tabId,
        { action: ExtensionAction.repEmbedded },
        (response: { isRepEmbedded: unknown }) => {
          const isRepEmbedded = !!response?.isRepEmbedded;
          resolve(isRepEmbedded);
        },
      );
    });
  };

  public getActiveTab(): Promise<chrome.tabs.Tab | undefined> {
    if (typeof window === 'undefined') return Promise.resolve(undefined);

    return new Promise((resolve) => {
      window.chrome.tabs.query(
        { active: true, currentWindow: true },
        (tabs: Array<chrome.tabs.Tab | undefined>) => {
          const activeTab = tabs[0];
          resolve(activeTab);
        },
      );
    });
  }

  public redirectActiveTab({ url }: { url: string }) {
    chrome.runtime.sendMessage({ action: ExtensionAction.redirect, newUrl: url });
  }

  public openNewTab({ url }: { url: string }) {
    chrome.runtime.sendMessage({ action: ExtensionAction.openNewTab, newUrl: url });
  }

  public get isChromeExtension() {
    if (this.config.isDevMode) {
      return true;
    }
    return (
      typeof window !== 'undefined' && window?.location?.protocol?.includes?.('chrome-extension')
    );
  }

  public emit<K extends ExtensionEvent>(eventName: K, ...args: Parameters<ExtensionEventMap[K]>) {
    this.listeners[eventName].forEach((listener) => {
      // TypeScript knows that listener’s signature matches args
      (listener as (...callbackArgs: unknown[]) => void)(...args);
    });
  }

  public communicateToExtension(
    action: ExtensionAction,
    data?: ExtensionEventMap[ExtensionEvent] | Record<string, unknown>,
  ): void {
    window.postMessage(
      {
        action,
        data,
      },
      '*',
    );
  }
}

export * from './constants';
export * from './utils';
