import { useContext } from 'react';
import { RepSocialContext, type RepSocialState } from '../context';

export const useRepSocial = (): RepSocialState => {
  if (typeof window === 'undefined') {
    return {
      communityUrl: '',
      communityUrlId: '',
      isEmbedded: false,
      isEmbeddedInIframe: false,
      isMobileEmbedded: false,
      isMobileIOSEmbedded: false,
      isExtension: false,
      isRepSocialIntegrated: false,
    };
  }

  const ctx = useContext(RepSocialContext);
  if (!ctx) {
    throw new Error('useRepSocial must be used inside <RepSocialProvider>');
  }
  return ctx;
};
